[
  {
    "sys_consequence_reasoning": "Five lives against an empty siding",
    "pda_harm_regret": "I'd carry the thought of those workers hurt",
    "pd_harm_distress": "my chest tightens thinking about what could've happened"
  },
  {
    "ce_mental_state_attribution": "workers not knowing death is rolling toward them",
    "pda_harm_regret": "that image would stay with me forever"
  },
  {
    "pda_harm_regret": "imagining if I'd hesitated... someone had been crushed"
  },
  {
    "pda_harm_regret": "I don't think I'd forgive myself",
    "pd_decision_conflict": "I hate that this is even happening"
  },
  {
    "pd_harm_distress": "that image alone makes my stomach turn",
    "pda_harm_regret": "picturing the men getting hurt anyway"
  },
  {
    "pda_harm_regret": "I'd never stop replaying it",
    "pda_responsibility": "because I couldn't act in time"
  },
  {
    "pda_harm_regret": "I'd have to live with that grief"
  },
  {
    "sys_consequence_reasoning": "saving the five",
    "pd_harm_distress": "just thinking about their suffering leaves something heavy",
    "pda_harm_regret": "I keep imagining... they're hurt anyway"
  },
  {
    "pda_harm_regret": "the thought of their pain... would never really leave me"
  },
  {
    "pd_decision_conflict": "It feels like sorrow with a decision attached",
    "pda_harm_regret": "if they'd been hurt... I don't think I could carry that weight"
  }
]
